// Handle BigDecimal conversion to string
protected String _asString(BigDecimal value) {
    if (Feature.WRITE_BIGDECIMAL_AS_PLAIN.enabledIn(_features)) {
        return value.toPlainString();
    }
    return value.toString();
}

// Ensure BigDecimal is written correctly
protected void _writeBigDecimal(BigDecimal value) throws IOException {
    if (Feature.WRITE_BIGDECIMAL_AS_PLAIN.enabledIn(_features)) {
        writeRaw(value.toPlainString());
    } else {
        writeRaw(value.toString());
    }
}

// Additional handling for BigDecimal
protected void _handleBigDecimal(BigDecimal value) throws IOException {
    if (value == null) {
        _writeNull();
    } else {
        _writeBigDecimal(value);
    }
}

